package com.harbourmaster.overlay;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.ApiStub;
import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.DockChecklist;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.NavigationPath;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.optimizer.RouteOptimizer;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class RouteOverlayTest {
    @Test
    public void routeGeometryPreservesStraightLinesInRotatedInstances() {
        int[][][] chunks = new int[4][13][13];
        chunks[0][0][0] = (320 << 14) | (400 << 3) | (1 << 1);
        WorldView world = ApiStub.of(WorldView.class, (method, arguments) -> {
            switch (method) {
                case "isInstance":
                    return true;
                case "getInstanceTemplateChunks":
                    return chunks;
                case "getBaseX":
                    return 10000;
                case "getBaseY":
                    return 10000;
                case "getPlane":
                    return 0;
                case "getSizeX":
                case "getSizeY":
                    return 104;
                case "getId":
                    return WorldView.TOPLEVEL;
                default:
                    throw new AssertionError(method);
            }
        });
        Client client = ApiStub.of(Client.class, (method, arguments) -> {
            if (method.equals("getTopLevelWorldView")) {
                return world;
            }
            throw new AssertionError(method);
        });
        NavigationPath diagonal = new NavigationPath(new RouteLeg(
                A, B, Math.hypot(5, 1), List.of(new WorldPoint(2561, 3201, 0), new WorldPoint(2566, 3202, 0))));
        LocalPoint start = NavigationOverlay.localPoint(client, diagonal.points.get(0));
        LocalPoint middle = NavigationOverlay.localPoint(client, diagonal.points.get(1));
        LocalPoint end = NavigationOverlay.localPoint(client, diagonal.points.get(2));
        assertEquals((start.getX() + end.getX()) / 2, middle.getX());
        assertEquals((start.getY() + end.getY()) / 2, middle.getY());
    }

    @Test
    public void missingRouteOriginStillRendersAnExplanation() {
        HarbourmasterSnapshot state = new HarbourmasterSnapshot(
                true,
                new RouteOptimizer(line()).optimize(null, List.of(accepted(courier(1, A, D, 100)))),
                List.of(),
                false,
                4,
                DockChecklist.at(null, List.of()),
                Map.of(),
                false);
        HarbourmasterPlugin plugin = new HarbourmasterPlugin() {
            @Override
            public HarbourmasterSnapshot getSnapshot() {
                return state;
            }
        };
        Graphics2D graphics = new BufferedImage(300, 300, BufferedImage.TYPE_INT_ARGB).createGraphics();
        try {
            Dimension rendered = new RouteStatusOverlay(plugin, new HarbourmasterConfig() {}).render(graphics);
            assertTrue(rendered.height > 0);
        } finally {
            graphics.dispose();
        }
    }
}

package com.harbourmaster.overlay;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.ApiStub;
import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.DockChecklist;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.tracker.CargoTracker;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class DockOverlayTest {
    private final List<ActiveTask> tasks = List.of(loaded(courier(1, A, B, 100)));
    private final CargoTracker cargo = new CargoTracker();
    private Item carried;
    private Port dock = A;
    private final WorldView boat = boat();
    private WorldView playerWorld = boat;
    private final Player player = ApiStub.of(Player.class, (method, arguments) -> {
        if (method.equals("getWorldView")) {
            return playerWorld;
        }
        throw new AssertionError(method);
    });
    private final ItemContainer equipment = ApiStub.of(ItemContainer.class, (method, arguments) -> {
        if (method.equals("getItem")) {
            assertEquals(EquipmentInventorySlot.WEAPON.getSlotIdx(), arguments[0]);
            return carried;
        }
        throw new AssertionError(method);
    });
    private final Client client = ApiStub.of(Client.class, (method, arguments) -> {
        switch (method) {
            case "getLocalPlayer":
                return player;
            case "getItemContainer":
                assertEquals(InventoryID.WORN, arguments[0]);
                return equipment;
            default:
                throw new AssertionError(method);
        }
    });
    private final HarbourmasterPlugin plugin = new HarbourmasterPlugin() {
        @Override
        public HarbourmasterSnapshot getSnapshot() {
            Map<Integer, CargoTracker.Destination> destinations = cargo.destinations(tasks, dock);
            return new HarbourmasterSnapshot(
                    true,
                    RoutePlan.empty(),
                    List.of(),
                    false,
                    4,
                    DockChecklist.at(dock, tasks),
                    destinations,
                    cargo.needsDeposit(client, destinations, dock));
        }
    };

    @Test
    public void carriedCrateHighlightsOwnHoldAfterPickupAndClearsAfterDeposit() {
        plugin.getPorts().add(hold(boat, 10));
        plugin.getPorts().add(hold(boat(), 70));
        carried = new Item(tasks.get(0).definition.itemId, 1);
        BufferedImage carrying = render();
        assertNotEquals(0, carrying.getRGB(20, 20));
        assertEquals(0, carrying.getRGB(80, 20));

        dock = null;
        assertNotEquals(0, render().getRGB(20, 20));

        carried = null;
        assertEquals(0, render().getRGB(20, 20));
        carried = new Item(999, 1);
        assertEquals(0, render().getRGB(20, 20));
    }

    @Test
    public void gangplankFollowsBoardingAndDockActionsWithoutMarkingOtherBoats() {
        WorldView shore = world(true);
        plugin.getPorts().add(object(shore, A.gangplankObject, 10));
        plugin.getPorts().add(object(shore, B.gangplankObject, 70));
        playerWorld = shore;
        carried = new Item(tasks.get(0).definition.itemId, 1);
        assertNotEquals(0, render().getRGB(20, 20));
        assertEquals(0, render().getRGB(80, 20));

        playerWorld = boat;
        assertEquals(0, render().getRGB(20, 20));
        plugin.getPorts().clear();
        plugin.getPorts().add(object(boat, ObjectID.SAILING_GANGPLANK_PROXY, 10));
        plugin.getPorts().add(object(boat(), ObjectID.SAILING_GANGPLANK_PROXY, 70));
        assertEquals(0, render().getRGB(20, 20));

        dock = B;
        assertNotEquals(0, render().getRGB(20, 20));
        assertEquals(0, render().getRGB(80, 20));
        dock = null;
        assertEquals(0, render().getRGB(20, 20));
    }

    @Test
    public void disembarkingCanUseThePortsShoreGangplank() {
        dock = B;
        WorldView shore = world(true);
        plugin.getPorts().add(object(shore, B.gangplankObject, 10));
        plugin.getPorts().add(object(shore, A.gangplankObject, 70));
        assertNotEquals(0, render().getRGB(20, 20));
        assertEquals(0, render().getRGB(80, 20));
    }

    @Test
    public void shoreGangplankLeadsBackToRemainingDeliveryCrates() {
        dock = B;
        playerWorld = world(true);
        plugin.getPorts().add(object(playerWorld, B.gangplankObject, 10));
        plugin.getPorts().add(object(playerWorld, A.gangplankObject, 70));
        assertNotEquals(0, render().getRGB(20, 20));
        assertEquals(0, render().getRGB(80, 20));

        carried = new Item(tasks.get(0).definition.itemId, 1);
        assertEquals(0, render().getRGB(20, 20));
    }

    private BufferedImage render() {
        BufferedImage image = new BufferedImage(120, 60, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try {
            new DockOverlay(client, plugin, new HarbourmasterConfig() {}).render(graphics);
            return image;
        } finally {
            graphics.dispose();
        }
    }

    private static WorldView boat() {
        return world(false, 1);
    }

    private static WorldView world(boolean topLevel) {
        return world(topLevel, 0);
    }

    private static WorldView world(boolean topLevel, int plane) {
        Tile[][][] tiles = new Tile[4][2][1];
        Scene scene = ApiStub.of(Scene.class, (method, arguments) -> {
            if (method.equals("getTiles")) {
                return tiles;
            }
            throw new AssertionError(method);
        });
        return ApiStub.of(WorldView.class, (method, arguments) -> {
            switch (method) {
                case "isTopLevel":
                    return topLevel;
                case "getPlane":
                    return plane;
                case "getScene":
                    return scene;
                default:
                    throw new AssertionError(method);
            }
        });
    }

    private static GameObject hold(WorldView boat, int horizontalPosition) {
        return object(boat, ObjectID.SAILING_BOAT_CARGO_HOLD_REGULAR_RAFT, horizontalPosition);
    }

    private static GameObject object(WorldView world, int identifier, int horizontalPosition) {
        boolean gangplank = identifier == ObjectID.SAILING_GANGPLANK_PROXY
                || Port.fromObject(identifier) != null && Port.fromObject(identifier).gangplankObject == identifier;
        GroundObject ground = ApiStub.of(GroundObject.class, (method, arguments) -> {
            switch (method) {
                case "getConvexHull":
                    return new Rectangle(horizontalPosition, 10, 20, 20);
                case "getCanvasTextLocation":
                    return null;
                default:
                    throw new AssertionError(method);
            }
        });
        world.getScene().getTiles()[0][horizontalPosition / 60][0] = ApiStub.of(Tile.class, (method, arguments) -> {
            if (method.equals("getGroundObject")) {
                return ground;
            }
            throw new AssertionError(method);
        });
        return ApiStub.of(GameObject.class, (method, arguments) -> {
            switch (method) {
                case "getId":
                    return identifier;
                case "getWorldView":
                    return world;
                case "getPlane":
                    return world.getPlane();
                case "getLocalLocation":
                    return new LocalPoint(horizontalPosition / 60 * 128 + 64, 64, 0);
                case "getConvexHull":
                    return gangplank ? null : new Rectangle(horizontalPosition, 10, 20, 20);
                case "getCanvasTextLocation":
                    return null;
                default:
                    throw new AssertionError(method);
            }
        });
    }
}

package com.harbourmaster.tracker;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.DockChecklist;
import com.harbourmaster.model.RouteEvent;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class CargoTrackerTest {
    @Test
    public void onlyCratesBoundForThisDockAreMarkedForUnloading() {
        CourierTask rum = courier(1, A, B, 100);
        CourierTask spice = courier(2, A, D, 100);
        Map<Integer, CargoTracker.Destination> cargo =
                new CargoTracker().destinations(List.of(loaded(rum), loaded(spice)), B);
        assertTrue(cargo.get(rum.itemId).unload);
        assertFalse(cargo.get(spice.itemId).unload);
        assertFalse(new CargoTracker().destinations(List.of(loaded(rum)), null).get(rum.itemId).unload);
    }

    @Test
    public void dockChecklistGroupsDeliveriesBeforeLoadsAndCountsOnlyAvailableCargo() {
        CourierTask partial = courier(1, A, B, 100);
        DockChecklist checklist = DockChecklist.at(
                B,
                List.of(
                        new ActiveTask(0, 1, partial, 2, 1),
                        loaded(courier(2, D, B, 100)),
                        accepted(courier(3, B, C, 100)),
                        accepted(courier(4, A, B, 100))));
        assertEquals(3, checklist.actions.size());
        assertEquals(RouteEvent.Action.DELIVER, checklist.actions.get(0).action);
        assertEquals(1, checklist.actions.get(0).quantity);
        assertEquals(RouteEvent.Action.DELIVER, checklist.actions.get(1).action);
        assertEquals(RouteEvent.Action.PICKUP, checklist.actions.get(2).action);
    }
}

package com.harbourmaster.tracker;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.data.PortPathData;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.DockChecklist;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.optimizer.RouteOptimizer;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class RouteTrackerTest {
    private final RouteTracker tracker = new RouteTracker(new RouteOptimizer(line()));

    @Test
    public void sailingPastAStopCannotAdvanceUntilAllItsDeliveriesAndPickupsFinish() {
        CourierTask unload = courier(1, A, B, 100);
        CourierTask load = courier(2, B, D, 100);
        List<ActiveTask> tasks = List.of(loaded(unload), accepted(load));
        assertSame(B, update(A, null, tasks).currentLeg.to);

        HarbourmasterSnapshot docked = update(B, B, tasks);
        assertSame(B, docked.nextPort());
        assertNull(docked.currentLeg);

        HarbourmasterSnapshot passed = update(D, null, tasks);
        assertSame(B, passed.currentLeg.to);
        assertSame(D, passed.currentLeg.from);

        tasks = List.of(new ActiveTask(1, unload.id, unload, 3, 1), new ActiveTask(2, load.id, load, 2, 0));
        HarbourmasterSnapshot partial = update(B, B, tasks);
        assertSame(B, partial.nextPort());
        assertNull(partial.currentLeg);

        tasks = List.of(new ActiveTask(1, unload.id, unload, 3, 3), new ActiveTask(2, load.id, load, 2, 0));
        HarbourmasterSnapshot stillLoading = update(B, B, tasks);
        assertSame(B, stillLoading.nextPort());
        assertNull(stillLoading.currentLeg);

        HarbourmasterSnapshot finished =
                update(B, B, List.of(new ActiveTask(1, unload.id, unload, 3, 3), loaded(load)));
        assertSame(D, finished.currentLeg.to);
        assertSame(B, finished.currentLeg.from);
    }

    @Test
    public void cancellingThePendingTaskReleasesItsStop() {
        ActiveTask remaining = loaded(courier(2, A, D, 100));
        assertSame(
                B,
                update(A, null, List.of(loaded(courier(1, A, B, 100)), remaining))
                        .nextPort());
        assertSame(D, update(D, D, List.of(remaining)).nextPort());
        assertTrue(update(D, D, List.of()).route.stops.isEmpty());
    }

    @Test
    public void acceptedTaskReplansToIncludeItsPickupBeforeLeavingTheCurrentPort() {
        ActiveTask held = loaded(courier(1, A, B, 100));
        assertSame(B, update(A, A, List.of(held)).nextPort());
        HarbourmasterSnapshot accepted = update(A, A, List.of(held, accepted(courier(2, A, D, 100))));
        assertSame(A, accepted.nextPort());
        assertNull(accepted.currentLeg);
    }

    @Test
    public void remotePickupDoesNotInterruptFourPendingDeliveries() {
        RouteTracker sailing = new RouteTracker(new RouteOptimizer(new PortGraph(PortPathData.load())));
        List<ActiveTask> deliveries = List.of(
                loaded(courier(1, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)),
                loaded(courier(2, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)),
                loaded(courier(3, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)),
                loaded(courier(4, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)));
        ActiveTask newTask = accepted(courier(5, Port.PORT_PISCARILIUS, Port.PORT_ROBERTS, 100));
        assertSame(
                Port.DEEPFIN_POINT,
                sailing.update(Port.PORT_ROBERTS, deliveries).stops.get(0).port);

        List<ActiveTask> held = new ArrayList<>(deliveries);
        held.add(newTask);
        assertSame(
                Port.DEEPFIN_POINT,
                sailing.update(Port.PORT_ROBERTS, held).stops.get(0).port);
        assertSame(
                Port.PORT_PISCARILIUS,
                sailing.update(Port.DEEPFIN_POINT, List.of(newTask)).stops.get(0).port);
    }

    @Test
    public void movingBoatUpdatesRemainingGeometryWithoutCompletingThePendingStop() {
        WorldPoint origin = new WorldPoint(100, 100, 0);
        WorldPoint bend = new WorldPoint(200, 100, 0);
        WorldPoint destination = new WorldPoint(200, 200, 0);
        RouteTracker moving = new RouteTracker(new RouteOptimizer(
                new PortGraph(List.of(new RouteLeg(A, B, 200, List.of(origin, bend, destination))))));
        List<ActiveTask> tasks = List.of(loaded(courier(1, A, B, 100)));
        RoutePlan route = moving.update(A, new WorldPoint(150, 100, 0), tasks);
        assertEquals(150, route.distance, 0.00001);
        assertEquals(List.of(new WorldPoint(150, 100, 0), bend, destination), route.legs.get(0).points);
        route = moving.update(A, new WorldPoint(200, 220, 0), tasks);
        assertEquals(20, route.distance, 0.00001);
        assertEquals(new WorldPoint(200, 220, 0), route.legs.get(0).points.get(0));
        assertSame(B, route.stops.get(0).port);
        route = moving.update(A, null, tasks);
        assertEquals(200, route.distance, 0.00001);
        assertSame(A, route.legs.get(0).from);
    }

    @Test
    public void initialOrderingUsesBoatPositionRatherThanLastPort() {
        WorldPoint origin = new WorldPoint(100, 100, 0);
        WorldPoint destination = new WorldPoint(300, 100, 0);
        RouteTracker moving = new RouteTracker(
                new RouteOptimizer(new PortGraph(List.of(new RouteLeg(A, B, 200, List.of(origin, destination))))));
        RoutePlan route = moving.update(
                A, new WorldPoint(280, 100, 0), List.of(loaded(courier(1, B, A, 100)), loaded(courier(2, A, B, 100))));
        assertSame(B, route.stops.get(0).port);
        assertEquals(220, route.distance, 0.00001);
    }

    private HarbourmasterSnapshot update(Port start, Port dock, List<ActiveTask> tasks) {
        return new HarbourmasterSnapshot(
                true,
                tracker.update(start, tasks),
                List.of(),
                false,
                5 - tasks.size(),
                DockChecklist.at(dock, tasks),
                Map.of(),
                false);
    }
}

package com.harbourmaster.tracker;

import static org.junit.Assert.*;

import com.harbourmaster.ApiStub;
import com.harbourmaster.model.Port;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class PortTrackerTest {
    private final PortTracker tracker = new PortTracker();
    private WorldPoint location = Port.PORT_SARIM.navigationLocation;
    private boolean entityAvailable = true;
    private boolean instance;
    private boolean aboard = true;
    private boolean atSea;
    private final int[][][] chunks = new int[4][13][13];
    private final WorldView boat = ApiStub.of(WorldView.class, (method, arguments) -> {
        switch (method) {
            case "isTopLevel":
                return false;
            case "getId":
                return 0;
            default:
                throw new AssertionError(method);
        }
    });
    private final Scene scene = ApiStub.of(Scene.class, (method, arguments) -> {
        if (method.equals("getTiles")) {
            return new Tile[0][][];
        }
        throw new AssertionError(method);
    });
    private final WorldEntity entity = ApiStub.of(WorldEntity.class, (method, arguments) -> {
        switch (method) {
            case "getLocalLocation":
            case "transformToMainWorld":
                return new LocalPoint(64, 64, WorldView.TOPLEVEL);
            case "getWorldView":
                return null;
            default:
                throw new AssertionError(method);
        }
    });
    private final IndexedObjectSet<WorldEntity> entities = new IndexedObjectSet<WorldEntity>() {
        @Override
        public WorldEntity byIndex(int index) {
            return entityAvailable ? entity : null;
        }

        @Override
        public java.util.Iterator<WorldEntity> iterator() {
            return List.of(entity).iterator();
        }
    };
    private final WorldView world = ApiStub.of(WorldView.class, (method, arguments) -> {
        switch (method) {
            case "isInstance":
                return instance;
            case "isTopLevel":
                return true;
            case "getId":
                return WorldView.TOPLEVEL;
            case "getPlane":
                return 0;
            case "getBaseX":
                return location.getX();
            case "getBaseY":
                return location.getY();
            case "getScene":
                return scene;
            case "getInstanceTemplateChunks":
                return chunks;
            case "worldEntities":
                return entities;
            default:
                throw new AssertionError(method);
        }
    });
    private final Player player = ApiStub.of(Player.class, (method, arguments) -> {
        switch (method) {
            case "getWorldView":
                return aboard ? boat : world;
            case "getLocalLocation":
                return new LocalPoint(64, 64, aboard ? 0 : WorldView.TOPLEVEL);
            default:
                throw new AssertionError(method);
        }
    });
    private final Client client = ApiStub.of(Client.class, (method, arguments) -> {
        switch (method) {
            case "getLocalPlayer":
                return player;
            case "getTopLevelWorldView":
            case "getWorldView":
                return world;
            case "getVarbitValue":
                assertEquals(VarbitID.SAILING_TRANSMIT_IS_AT_SEA, arguments[0]);
                return atSea ? 1 : 0;
            default:
                throw new AssertionError(method);
        }
    });

    @Test
    public void voyageKeepsOriginAndBoatPositionAcrossSceneChanges() {
        tracker.update(client, Port.PORT_SARIM);
        assertNull(tracker.getBoatPosition());
        location = new WorldPoint(1000, 1000, 0);
        tracker.update(client, null);
        assertSame(Port.PORT_SARIM, tracker.getStart());
        assertEquals(location, tracker.getBoatPosition());
        entityAvailable = false;
        tracker.update(client, null);
        assertSame(Port.PORT_SARIM, tracker.getStart());
        assertEquals(location, tracker.getBoatPosition());
        entityAvailable = true;
        aboard = false;
        location = Port.PORT_SARIM.navigationLocation;
        tracker.update(client, null);
        assertSame(Port.PORT_SARIM, tracker.getStart());
        assertNull(tracker.getBoatPosition());
        tracker.update(client, Port.BRIMHAVEN);
        assertSame(Port.BRIMHAVEN, tracker.getStart());
    }

    @Test
    public void boatPositionUsesOuterInstanceCoordinates() {
        instance = true;
        chunks[0][0][0] = (320 << 14) | (400 << 3);
        assertEquals(new WorldPoint(2560, 3200, 0), PortTracker.position(client));
    }

    @Test
    public void sceneScanToleratesAnEntityWhoseWorldViewIsNotLoadedYet() {
        tracker.scanScene(client);
    }

    @Test
    public void boatAtPortRobertsRecognizesDockWithDistantBoard() {
        location = Port.PORT_ROBERTS.navigationLocation;
        atSea = true;
        tracker.add(ApiStub.of(GameObject.class, (method, arguments) -> {
            switch (method) {
                case "getId":
                    return Port.PORT_ROBERTS.noticeboardObject;
                case "getWorldView":
                    return world;
                case "getLocalLocation":
                    return new LocalPoint(64 + 30 * 128, 64, WorldView.TOPLEVEL);
                default:
                    throw new AssertionError(method);
            }
        }));

        tracker.update(client, null);
        assertSame(Port.PORT_ROBERTS, tracker.getDock());

        atSea = false;
        tracker.update(client, null);
        assertSame(Port.PORT_ROBERTS, tracker.getDock());
    }
}

package com.harbourmaster.tracker;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.DockChecklist;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.optimizer.RouteOptimizer;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class ActiveTaskTrackerTest {
    private final ActiveTaskTracker tracker = new ActiveTaskTracker();
    private final CourierTask courier = courier(1, A, D, 100);
    private final Map<Integer, Integer> varbits = new HashMap<>();
    private final Map<Integer, Integer> varplayers = new HashMap<>();
    private final Map<Integer, CourierTask> catalog = new HashMap<>(Map.of(1, courier));
    private Port port = A;

    @Test
    public void allFiveSlotsAreReadFreshAndLoginReplayCannotDuplicateThem() {
        assertTrue(read().isEmpty());
        for (int slot = 0; slot < 5; slot++) {
            varbits.put(TaskVarbits.IDS[slot], slot + 1);
            catalog.put(slot + 1, courier(slot + 1, A, D, 100));
        }
        List<ActiveTask> first = read();
        assertEquals(5, first.size());
        assertEquals(first, read());
        assertEquals(4, first.get(4).slot);
        varbits.put(TaskVarbits.IDS[1], 0);
        assertEquals(4, read().size());
    }

    @Test
    public void deliveredTaskOccupiesSlotUntilCleared() {
        progress(3, 3);
        assertEquals(1, tracker.occupiedSlots(id -> varbits.getOrDefault(id, 0)));
        varbits.put(TaskVarbits.IDS[0], 0);
        assertEquals(0, tracker.occupiedSlots(id -> varbits.getOrDefault(id, 0)));
    }

    @Test
    public void crewPickupUpdatesChecklistAndRouteBeforeDepositWithoutCountingTwice() {
        List<ActiveTask> beforePickup = List.of(progress(1, 0));
        assertEquals(2, DockChecklist.at(A, beforePickup).actions.get(0).quantity);

        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_0, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT, 1);
        assertEquals(1, DockChecklist.at(A, read()).actions.get(0).quantity);
        assertNotEquals(beforePickup, read());

        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_1, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_1_AMOUNT, 1);
        List<ActiveTask> withCrew = read();
        assertTrue(DockChecklist.at(A, withCrew).actions.isEmpty());
        RoutePlan route = new RouteOptimizer(line()).optimize(A, withCrew);
        assertEquals(
                List.of(RouteEvent.Action.DELIVER),
                route.stops.stream()
                        .flatMap(stop -> stop.events.stream())
                        .map(event -> event.action)
                        .collect(Collectors.toList()));
        varbits.put(TaskVarbits.TAKEN[0], 2);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT, 0);
        assertEquals(withCrew, read());
        varbits.put(TaskVarbits.TAKEN[0], 3);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_1_AMOUNT, 0);
        assertEquals(withCrew, read());
    }

    @Test
    public void crewCargoUsesQuantityAndItemIdentity() {
        progress(0, 0);
        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_4, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_4_AMOUNT, 2);
        assertEquals(1, DockChecklist.at(A, read()).actions.get(0).quantity);

        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_4, courier(2, A, B, 100).itemId);
        assertEquals(3, DockChecklist.at(A, read()).actions.get(0).quantity);
    }

    @Test
    public void withdrawingCargoForPartialDeliveryDoesNotPretendMoreWasPickedUp() {
        progress(1, 0);
        port = D;
        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_0, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT, 1);
        assertEquals(2, read().get(0).pickupRemaining());
        assertEquals(1, DockChecklist.at(D, read()).actions.get(0).quantity);
    }

    private ActiveTask progress(int taken, int delivered) {
        varbits.put(TaskVarbits.IDS[0], 1);
        varbits.put(TaskVarbits.TAKEN[0], taken);
        varbits.put(TaskVarbits.DELIVERED[0], delivered);
        return read().get(0);
    }

    private List<ActiveTask> read() {
        return tracker.read(
                id -> varbits.getOrDefault(id, 0),
                id -> varplayers.getOrDefault(id, 0),
                catalog::get,
                id -> false,
                port);
    }
}

