package com.harbourmaster;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteLeg;
import java.util.List;

public final class Fixtures {
    public static final Port A = Port.PORT_SARIM;
    public static final Port B = Port.MUSA_POINT;
    public static final Port C = Port.BRIMHAVEN;
    public static final Port D = Port.CATHERBY;
    public static final Port E = Port.ARDOUGNE;

    private Fixtures() {}

    public static CourierTask courier(int id, Port pickup, Port delivery, int experience) {
        return new CourierTask(id, id, "Task " + id, 1, A, 100 + id, "Cargo " + id, 3, experience, pickup, delivery);
    }

    public static ActiveTask accepted(CourierTask task) {
        return new ActiveTask(task.id, task.id, task, 0, 0);
    }

    public static ActiveTask loaded(CourierTask task) {
        return new ActiveTask(task.id, task.id, task, task.quantity, 0);
    }

    public static RouteLeg edge(Port from, Port to, double length) {
        return new RouteLeg(from, to, length, List.of(from.navigationLocation, to.navigationLocation));
    }

    public static PortGraph line() {
        return new PortGraph(List.of(edge(A, B, 10), edge(B, C, 10), edge(C, D, 10), edge(B, E, 5)));
    }
}

package com.harbourmaster.data;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.ApiStub;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.optimizer.RouteOptimizer;
import com.harbourmaster.tracker.ActiveTaskTracker;
import com.harbourmaster.tracker.NoticeboardTracker;
import com.harbourmaster.tracker.TaskVarbits;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

public class RuntimeIntegrationTest {
    private final Map<Integer, Map<String, Object>> rows = new HashMap<>();
    private boolean boardHidden;
    private boolean detailsOpen;
    private Widget[] entries = new Widget[0];
    private final Widget board = ApiStub.of(Widget.class, (method, arguments) -> {
        switch (method) {
            case "isHidden":
                return boardHidden;
            case "getDynamicChildren":
                return entries;
            default:
                throw new AssertionError(method);
        }
    });
    private final Widget detailsWindow = ApiStub.of(Widget.class, (method, arguments) -> {
        if (method.equals("isHidden")) {
            return false;
        }
        throw new AssertionError(method);
    });
    private final Client client = ApiStub.of(Client.class, (method, arguments) -> {
        switch (method) {
            case "getDBTableRows":
                return List.copyOf(rows.keySet());
            case "getDBTableField":
                Object field = rows.get(arguments[0]).get(arguments[1] + ":" + arguments[2]);
                return field == null ? new Object[0] : new Object[] {field};
            case "getItemDefinition":
                return ApiStub.of(ItemComposition.class, (itemMethod, itemArguments) -> {
                    if (itemMethod.equals("getName")) {
                        return "Runtime cargo";
                    }
                    throw new AssertionError(itemMethod);
                });
            case "getWidget":
                if (arguments[0].equals(InterfaceID.PortTaskInfo.WINDOW)) {
                    return detailsOpen ? detailsWindow : null;
                }
                return arguments[0].equals(InterfaceID.PortTaskBoard.CONTAINER) ? board : null;
            default:
                throw new AssertionError(method);
        }
    });

    @Test
    public void catalogueReadsCourierCargoFromRuntime() {
        Map<String, Object> courier = row(1, 0);
        courier.put(DBTableID.PortTask.COL_CARGO + ":0", 200);
        courier.put(DBTableID.PortTask.COL_CARGO + ":1", 3);
        rows.put(8664, courier);
        PortTaskCatalog catalog = new PortTaskCatalog();
        catalog.load(client);
        CourierTask loaded = catalog.byId(1);
        assertEquals(3, loaded.quantity);
        assertEquals(200, loaded.itemId);
        assertEquals(A, loaded.pickup);
        assertEquals(D, loaded.delivery);
    }

    @Test
    public void nonCourierRowsAreIgnoredWithoutLosingTheirOccupiedSlots() {
        Map<String, Object> courier = row(1, 0);
        courier.put(DBTableID.PortTask.COL_CARGO + ":0", 200);
        courier.put(DBTableID.PortTask.COL_CARGO + ":1", 3);
        rows.put(8664, courier);
        rows.put(99998, row(2, 1));
        PortTaskCatalog catalog = new PortTaskCatalog();
        catalog.load(client);
        Map<Integer, Integer> varbits = Map.of(TaskVarbits.IDS[0], 1, TaskVarbits.IDS[1], 2);
        ActiveTaskTracker active = new ActiveTaskTracker();
        List<ActiveTask> tasks =
                active.read(id -> varbits.getOrDefault(id, 0), id -> 0, catalog::byId, catalog::isIgnoredTask, A);
        assertEquals(1, tasks.size());
        assertEquals(2, active.occupiedSlots(id -> varbits.getOrDefault(id, 0)));
        assertTrue(new RouteOptimizer(line()).optimize(A, tasks).available);
        entries = new Widget[] {entry(new Object[] {1, 2, 3, 8664}), entry(new Object[] {1, 2, 3, 99998})};
        NoticeboardTracker board = new NoticeboardTracker();
        board.scan(client, catalog);
        assertEquals(1, board.getOffers().size());
        assertEquals(1, board.getWidgets().size());
    }

    @Test
    public void boardReadsTaskEntriesAndStopsHighlightingWhenClosed() {
        Map<String, Object> courier = row(1, 0);
        courier.put(DBTableID.PortTask.COL_CARGO + ":0", 200);
        courier.put(DBTableID.PortTask.COL_CARGO + ":1", 3);
        rows.put(8664, courier);
        PortTaskCatalog catalog = new PortTaskCatalog();
        catalog.load(client);
        entries = new Widget[] {entry(new Object[] {1, 2, 3, 8664}), entry(new Object[] {1, 2, 3, 8664}), entry(null)};
        NoticeboardTracker tracker = new NoticeboardTracker();
        tracker.scan(client, catalog);
        assertTrue(tracker.isOpen());
        assertEquals(1, tracker.getOffers().size());
        assertEquals(A, tracker.getPort());
        boardHidden = true;
        tracker.scan(client, catalog);
        assertFalse(tracker.isOpen());
        assertTrue(tracker.getWidgets().isEmpty());
    }

    @Test
    public void rebuildingBoardClearsPreviousOffersAndPort() {
        Map<String, Object> courier = row(1, 0);
        courier.put(DBTableID.PortTask.COL_CARGO + ":0", 200);
        courier.put(DBTableID.PortTask.COL_CARGO + ":1", 3);
        rows.put(8664, courier);
        PortTaskCatalog catalog = new PortTaskCatalog();
        catalog.load(client);
        entries = new Widget[] {entry(new Object[] {1, 2, 3, 8664})};
        NoticeboardTracker tracker = new NoticeboardTracker();
        tracker.scan(client, catalog);
        assertEquals(A, tracker.getPort());

        entries = null;
        tracker.scan(client, catalog);

        assertTrue(tracker.isOpen());
        assertTrue(tracker.getOffers().isEmpty());
        assertTrue(tracker.getWidgets().isEmpty());
        assertNull(tracker.getPort());
    }

    @Test
    public void openingTaskDetailsPreservesBoardOffersUntilTheWindowCloses() {
        for (int databaseRow : List.of(8664, 8665)) {
            Map<String, Object> courier = row(databaseRow - 8663, 0);
            courier.put(DBTableID.PortTask.COL_CARGO + ":0", 200);
            courier.put(DBTableID.PortTask.COL_CARGO + ":1", 3);
            rows.put(databaseRow, courier);
        }
        PortTaskCatalog catalog = new PortTaskCatalog();
        catalog.load(client);
        entries = new Widget[] {entry(new Object[] {1, 2, 3, 8664}), entry(new Object[] {1, 2, 3, 8665})};
        NoticeboardTracker tracker = new NoticeboardTracker();
        tracker.scan(client, catalog);
        tracker.beginOpeningDetails(entry(null));
        tracker.beginOpeningDetails(entries[0]);

        boardHidden = true;
        tracker.scan(client, catalog);
        assertEquals(2, tracker.getOffers().size());

        detailsOpen = true;
        entries = new Widget[] {entry(new Object[] {1, 2, 3, 8665})};
        tracker.scan(client, catalog);
        assertEquals(2, tracker.getOffers().size());

        detailsOpen = false;
        boardHidden = false;
        tracker.scan(client, catalog);
        assertEquals(1, tracker.getOffers().size());
        assertEquals(8665, tracker.getOffers().get(0).databaseRow);
    }

    private static Widget entry(Object[] listener) {
        return ApiStub.of(Widget.class, (method, arguments) -> {
            if (method.equals("getOnOpListener")) {
                return listener;
            }
            throw new AssertionError(method);
        });
    }

    private static Map<String, Object> row(int id, int type) {
        Map<String, Object> fields = new HashMap<>();
        fields.put(DBTableID.PortTask.COL_TASK_ID + ":0", id);
        fields.put(DBTableID.PortTask.COL_NAME + ":0", "Runtime task");
        fields.put(DBTableID.PortTask.COL_TASK_TYPE + ":0", type);
        fields.put(DBTableID.PortTask.COL_LEVEL_REQUIRED + ":0", 1);
        fields.put(DBTableID.PortTask.COL_STARTING_PORT + ":0", A.databaseRow);
        fields.put(DBTableID.PortTask.COL_CARGO_PORT + ":0", A.databaseRow);
        fields.put(DBTableID.PortTask.COL_ENDING_PORT + ":0", D.databaseRow);
        return fields;
    }
}

package com.harbourmaster.data;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteLeg;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class PortGraphTest {
    @Test
    public void shortestPathUsesIntermediatePortsAndReversesGeometryWithoutMutation() {
        PortGraph graph = new PortGraph(List.of(edge(A, B, 10), edge(B, C, 10), edge(A, C, 50)));
        RouteLeg forward = graph.route(A, C).get();
        RouteLeg reverse = graph.route(C, A).get();
        assertEquals(20, forward.distance, 0);
        assertEquals(List.of(C.navigationLocation, B.navigationLocation, A.navigationLocation), reverse.points);
        assertEquals(A.navigationLocation, forward.points.get(0));
    }

    @Test
    public void offPathBoatJoinsAheadWhilePreservingTheMappedCorner() {
        WorldPoint origin = new WorldPoint(100, 100, 0);
        WorldPoint corner = new WorldPoint(100, 200, 0);
        WorldPoint destination = new WorldPoint(200, 200, 0);
        PortGraph graph = new PortGraph(List.of(new RouteLeg(A, B, 200, List.of(origin, corner, destination))));
        WorldPoint boat = new WorldPoint(105, 100, 0);
        RouteLeg route = graph.routeFromPosition(boat, B).orElseThrow();
        assertEquals(boat, route.points.get(0));
        assertTrue(
                "Join ahead instead of sailing sideways and turning 90 degrees",
                route.points.get(1).getY() > 110);
        assertTrue(route.points.contains(corner));
        assertEquals(destination, route.points.get(route.points.size() - 1));
    }

    @Test
    public void adjacentVarlamorePathsDoNotSendTheBoatViaUnrelatedPorts() {
        PortGraph graph = new PortGraph(PortPathData.load());
        RouteLeg previous = null;
        for (int horizontal = 1890; horizontal <= 1940; horizontal += 5) {
            WorldPoint position = new WorldPoint(horizontal, 2940, 0);
            RouteLeg route =
                    graph.routeFromPosition(position, Port.CIVITAS_ILLA_FORTIS).orElseThrow();
            assertTrue("Unexpected detour at " + position, route.distance < 500);
            if (previous != null) {
                assertTrue(
                        "Five tiles of movement must not add a distant port detour",
                        Math.abs(previous.distance - route.distance) < 20);
            }
            previous = route;
        }
        double measured = 0;
        for (int index = 1; index < previous.points.size(); index++) {
            WorldPoint from = previous.points.get(index - 1);
            WorldPoint to = previous.points.get(index);
            measured += Math.hypot(to.getX() - from.getX(), to.getY() - from.getY());
        }
        assertEquals(measured, previous.distance, 0.00001);
    }

    @Test
    public void packagedNavigationDataProducesContinuousMeasuredRoutes() {
        PortGraph graph = new PortGraph(PortPathData.load());
        RouteLeg route = graph.route(A, Port.LUNAR_ISLE).get();
        double measured = 0;
        for (int index = 1; index < route.points.size(); index++) {
            measured += Math.hypot(
                    route.points.get(index).getX() - route.points.get(index - 1).getX(),
                    route.points.get(index).getY() - route.points.get(index - 1).getY());
        }
        assertEquals(measured, route.distance, 0.00001);
        assertEquals(A.navigationLocation, route.points.get(0));
        assertEquals(Port.LUNAR_ISLE.navigationLocation, route.points.get(route.points.size() - 1));
    }
}

package com.harbourmaster.optimizer;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.data.PortPathData;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.OfferBundle;
import com.harbourmaster.model.OfferScore;
import com.harbourmaster.model.Port;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class OfferRankerTest {
    private final RouteOptimizer optimizer = new RouteOptimizer(line());
    private final OfferRanker ranker = new OfferRanker(optimizer);

    @Test
    public void marginalValueBeatsBetterStandaloneExperiencePerTile() {
        CourierTask standaloneWinner = courier(2, B, E, 1000);
        CourierTask marginalWinner = courier(3, B, C, 100);
        List<ActiveTask> active = List.of(accepted(courier(1, A, D, 100)));
        List<OfferScore> scores =
                ranker.rank(A, active, List.of(standaloneWinner, marginalWinner), 99, 4, optimizer.optimize(A, active));
        assertEquals(List.of(marginalWinner), scores.get(1).bundle.tasks);
        assertTrue(scores.get(1).freeTravel);
        assertEquals(0, scores.get(1).marginalDistance, 0);
        assertNull(scores.get(0).bundle);
        assertEquals(10, scores.get(0).marginalDistance, 0.00001);
        assertEquals(100, scores.get(0).score, 0.00001);
    }

    @Test
    public void equalMarginalEfficiencyUsesExperienceAsTieBreaker() {
        List<OfferScore> scores = ranker.rank(
                A,
                List.of(),
                List.of(courier(1, A, B, 100), courier(2, A, C, 200)),
                99,
                1,
                optimizer.optimize(A, List.of()));
        assertNull(scores.get(0).bundle);
        assertEquals(2, scores.get(1).bundle.tasks.get(0).id);
    }

    @Test
    public void heldAndLevelGatedJobsAreNotRecommended() {
        CourierTask held = courier(1, A, D, 100);
        CourierTask gated = new CourierTask(3, 3, "High level", 99, A, 103, "Cargo", 3, 10000, A, B);
        List<ActiveTask> active = List.of(accepted(held));
        List<OfferScore> scores = ranker.rank(
                A, active, List.of(held, gated, courier(5, B, C, 100)), 50, 4, optimizer.optimize(A, active));
        assertNull(scores.get(0).bundle);
        assertNull(scores.get(1).bundle);
        assertEquals(5, scores.get(2).bundle.tasks.get(0).id);
    }

    @Test
    public void unknownExperienceIsNotRecommended() {
        List<CourierTask> offers = List.of(courier(1, A, B, -1));
        List<OfferScore> scores = ranker.rank(A, List.of(), offers, 99, 5, optimizer.optimize(A, List.of()));
        assertNull(scores.get(0).bundle);
    }

    @Test
    public void sharedCrossingBundleBeatsTheBestIndividualOfferAndRespectsCapacity() {
        CourierTask individual = courier(1, A, B, 150);
        CourierTask outbound = courier(2, A, D, 300);
        CourierTask companion = courier(3, A, D, 300);
        List<CourierTask> offers = List.of(individual, outbound, companion);
        List<OfferScore> scores = ranker.rank(A, List.of(), offers, 99, 2, optimizer.optimize(A, List.of()));
        assertNull(scores.get(0).bundle);
        OfferBundle bundle = scores.get(1).bundle;
        assertNotNull(scores.get(2).bundle);
        assertEquals(Set.of(outbound, companion), Set.copyOf(bundle.tasks));
        assertEquals(600, bundle.experience);
        assertEquals(30, bundle.marginalDistance, 0.00001);
        assertEquals(20, bundle.score, 0.00001);
        List<OfferScore> single = ranker.rank(A, List.of(), offers, 99, 1, optimizer.optimize(A, List.of()));
        assertEquals(List.of(individual), single.get(0).bundle.tasks);
        assertNull(single.get(1).bundle);
        assertNull(single.get(2).bundle);
        List<ActiveTask> held = List.of(accepted(outbound));
        scores = ranker.rank(A, held, offers, 99, 2, optimizer.optimize(A, held));
        OfferBundle remaining = scores.stream()
                .filter(score -> score.bundle != null)
                .findFirst()
                .orElseThrow()
                .bundle;
        assertEquals(Set.of(individual, companion), Set.copyOf(remaining.tasks));
        assertTrue(remaining.freeTravel);
        assertEquals(450, remaining.experience);
    }

    @Test
    public void fullSlotsDoNotRecommendAcceptingAnotherTask() {
        List<OfferScore> scores =
                ranker.rank(A, List.of(), List.of(courier(1, A, B, 100)), 99, 0, optimizer.optimize(A, List.of()));
        assertFalse(scores.get(0).eligible());
        assertNull(scores.get(0).bundle);
    }

    @Test
    public void remoteOfferDoesNotOutrankFourLoadedDeliveries() {
        RouteOptimizer sailing = new RouteOptimizer(new PortGraph(PortPathData.load()));
        OfferRanker offers = new OfferRanker(sailing);
        List<ActiveTask> held = List.of(
                loaded(courier(1, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)),
                loaded(courier(2, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)),
                loaded(courier(3, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)),
                loaded(courier(4, Port.PORT_ROBERTS, Port.DEEPFIN_POINT, 100)));
        CourierTask fish = courier(5, Port.PORT_PISCARILIUS, Port.PORT_ROBERTS, 100);

        OfferScore score = offers.rank(
                        Port.PORT_ROBERTS,
                        held,
                        List.of(fish),
                        99,
                        1,
                        sailing.optimizeForExperience(Port.PORT_ROBERTS, held))
                .get(0);
        assertTrue(score.eligible());
        assertTrue(score.marginalDistance > 1000);
        assertNull(score.bundle);
    }

    @Test
    public void deliveryWithoutABoardNeedsAnOnwardTaskBeforeItIsRecommended() {
        RouteOptimizer sailing = new RouteOptimizer(new PortGraph(PortPathData.load()));
        OfferRanker offers = new OfferRanker(sailing);
        CourierTask stranded = courier(1, Port.PORT_PISCARILIUS, Port.PISCATORIS, 1000);
        CourierTask returnTask = courier(2, Port.PISCATORIS, Port.PORT_PISCARILIUS, 100);
        assertNull(offers.rank(
                        Port.PORT_PISCARILIUS,
                        List.of(),
                        List.of(stranded),
                        99,
                        2,
                        sailing.optimizeForExperience(Port.PORT_PISCARILIUS, List.of()))
                .get(0)
                .bundle);

        List<OfferScore> scores = offers.rank(
                Port.PORT_PISCARILIUS,
                List.of(),
                List.of(stranded, returnTask),
                99,
                2,
                sailing.optimizeForExperience(Port.PORT_PISCARILIUS, List.of()));
        assertEquals(Set.of(stranded, returnTask), Set.copyOf(scores.get(0).bundle.tasks));
        assertNotNull(scores.get(1).bundle);

        CourierTask companion = courier(3, Port.PORT_PISCARILIUS, Port.PISCATORIS, 100);
        List<ActiveTask> held = List.of(loaded(stranded));
        assertEquals(
                List.of(companion),
                offers.rank(
                                Port.PORT_PISCARILIUS,
                                held,
                                List.of(companion),
                                99,
                                1,
                                sailing.optimizeForExperience(Port.PORT_PISCARILIUS, held))
                        .get(0)
                        .bundle
                        .tasks);
    }
}

package com.harbourmaster.optimizer;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RoutePlan;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;

public class RouteOptimizerTest {
    private final RouteOptimizer optimizer = new RouteOptimizer(line());

    @Test
    public void singleTaskReconstructsPickupDeliveryAndTravelDistance() {
        RoutePlan plan = optimizer.optimize(A, List.of(accepted(courier(1, B, D, 100))));
        assertEquals(30, plan.distance, 0.00001);
        assertEquals(List.of(RouteEvent.Action.PICKUP, RouteEvent.Action.DELIVER), actions(plan));
        assertEquals(List.of(B, D), ports(plan));
        assertEquals(
                plan.distance,
                plan.legs.stream().mapToDouble(leg -> leg.distance).sum(),
                0.00001);
    }

    @Test
    public void cannotDeliverBeforePickupEvenWhenStandingAtDelivery() {
        RoutePlan plan = optimizer.optimize(A, List.of(accepted(courier(1, D, A, 100))));
        assertEquals(List.of(D, A), ports(plan));
        assertEquals(60, plan.distance, 0.00001);
    }

    @Test
    public void fullyLoadedCargoNeedsOnlyImmediateDelivery() {
        RoutePlan plan = optimizer.optimize(A, List.of(loaded(courier(1, D, A, 100))));
        assertEquals(0, plan.distance, 0);
        assertEquals(List.of(RouteEvent.Action.DELIVER), actions(plan));
        assertTrue(plan.legs.isEmpty());
    }

    @Test
    public void pickupAndDeliveryAtSamePortDoNotCauseReturnTrip() {
        RoutePlan plan =
                optimizer.optimize(A, List.of(accepted(courier(1, A, B, 100)), accepted(courier(2, B, D, 100))));
        assertEquals(30, plan.distance, 0.00001);
        assertEquals(
                List.of(A, B, D), plan.stops.stream().map(stop -> stop.port).collect(Collectors.toList()));
        assertEquals(2, plan.stops.get(1).events.size());
    }

    @Test
    public void partialProgressOnlyPlansOutstandingCratesAndSkipsCompletedTasks() {
        CourierTask task = courier(1, B, D, 100);
        RoutePlan plan = optimizer.optimize(
                A, List.of(new ActiveTask(0, 1, task, 2, 1), new ActiveTask(1, 2, courier(2, E, C, 100), 3, 3)));
        assertEquals(
                List.of(1, 2),
                plan.stops.stream()
                        .flatMap(stop -> stop.events.stream())
                        .map(event -> event.quantity)
                        .collect(Collectors.toList()));
    }

    @Test
    public void optimumAgreesWithIndependentExhaustiveSearch() {
        Random random = new Random(20260921);
        Port[] ports = {A, B, C, D, E};
        for (int example = 0; example < 20; example++) {
            List<ActiveTask> tasks = new ArrayList<>();
            for (int id = 1; id <= 3; id++) {
                Port pickup = ports[random.nextInt(ports.length)];
                Port delivery = ports[random.nextInt(ports.length)];
                tasks.add(accepted(courier(id, pickup, delivery, 100)));
            }
            Port start = ports[random.nextInt(ports.length)];
            assertEquals(
                    brute(line(), start, tasks, new HashSet<>(), new HashSet<>()),
                    optimizer.optimize(start, tasks).distance,
                    0.00001);
        }
    }

    private static double brute(
            PortGraph graph, Port from, List<ActiveTask> tasks, Set<Integer> picked, Set<Integer> delivered) {
        if (delivered.size() == tasks.size()) {
            return 0;
        }
        double best = Double.POSITIVE_INFINITY;
        for (ActiveTask active : tasks) {
            CourierTask task = active.definition;
            if (delivered.contains(task.id)) {
                continue;
            }
            boolean pickup = !picked.contains(task.id);
            Port destination = pickup ? task.pickup : task.delivery;
            Set<Integer> changed = pickup ? picked : delivered;
            changed.add(task.id);
            best = Math.min(
                    best,
                    graph.route(from, destination).get().distance
                            + brute(graph, destination, tasks, picked, delivered));
            changed.remove(task.id);
        }
        return best;
    }

    private static List<Port> ports(RoutePlan plan) {
        return plan.stops.stream()
                .flatMap(stop -> stop.events.stream())
                .map(event -> event.port)
                .collect(Collectors.toList());
    }

    private static List<RouteEvent.Action> actions(RoutePlan plan) {
        return plan.stops.stream()
                .flatMap(stop -> stop.events.stream())
                .map(event -> event.action)
                .collect(Collectors.toList());
    }
}

package com.harbourmaster;

import java.lang.reflect.Proxy;
import java.util.function.BiFunction;

public final class ApiStub {
    private ApiStub() {}

    public static <T> T of(Class<T> type, BiFunction<String, Object[], Object> methods) {
        return type.cast(
                Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type}, (proxy, method, arguments) -> {
                    if (method.getDeclaringClass() == Object.class) {
                        switch (method.getName()) {
                            case "hashCode":
                                return System.identityHashCode(proxy);
                            case "equals":
                                return proxy == arguments[0];
                            case "toString":
                                return "Stub " + type.getSimpleName();
                            default:
                                throw new AssertionError(method.getName());
                        }
                    }
                    return methods.apply(method.getName(), arguments);
                }));
    }
}

