@PluginDescriptor(
        name = "Harbourmaster",
        description = "Optimizes Sailing courier routes and suggests tasks, with cargo and dock guidance",
        tags = {"sailing", "port", "courier", "cargo", "tasks", "route", "optimizer", "navigation"})
public class HarbourmasterPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private HarbourmasterConfig config;

    @Inject
    private PortTaskCatalog catalog;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private NoticeboardOverlay noticeboardOverlay;

    @Inject
    private DockOverlay dockOverlay;

    @Inject
    private CargoOverlay cargoOverlay;

    @Inject
    private NavigationOverlay navigationOverlay;

    @Inject
    private MinimapRouteOverlay minimapOverlay;

    @Inject
    private WorldMapRouteOverlay worldMapOverlay;

    @Inject
    private RouteStatusOverlay statusOverlay;

    private final ActiveTaskTracker activeTasks = new ActiveTaskTracker();
    private final NoticeboardTracker noticeboard = new NoticeboardTracker();
    private final PortTracker ports = new PortTracker();
    private final CargoTracker cargo = new CargoTracker();
    private final RouteOptimizer optimizer = new RouteOptimizer(new PortGraph(PortPathData.load()));
    private final RouteTracker routeTracker = new RouteTracker(optimizer);
    private final OfferRanker ranker = new OfferRanker(optimizer);
    private volatile HarbourmasterSnapshot snapshot = HarbourmasterSnapshot.empty();
    private volatile boolean running;
    private List<Object> previousInputs;

    @Provides
    HarbourmasterConfig provideConfig(ConfigManager manager) {
        return manager.getConfig(HarbourmasterConfig.class);
    }

    @Override
    protected void startUp() throws Exception {
        running = true;
        for (Overlay overlay : overlays()) {
            overlayManager.add(overlay);
        }
        clientThread.invokeLater(() -> {
            if (running && client.getGameState() == GameState.LOGGED_IN) {
                ports.scanScene(client);
                refresh();
            }
        });
    }

    @Override
    protected void shutDown() throws Exception {
        running = false;
        for (Overlay overlay : overlays()) {
            overlayManager.remove(overlay);
        }
        clientThread.invokeLater(this::clear);
    }

    private List<Overlay> overlays() {
        return List.of(
                noticeboardOverlay,
                dockOverlay,
                cargoOverlay,
                navigationOverlay,
                minimapOverlay,
                worldMapOverlay,
                statusOverlay);
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (running) {
            refresh();
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        Widget details = client.getWidget(InterfaceID.PortTaskInfo.WINDOW);
        if (noticeboard.isOpen() && (details == null || details.isHidden())) {
            noticeboard.beginOpeningDetails(event.getWidget());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING) {
            clear();
        } else if (event.getGameState() == GameState.LOGGED_IN) {
            ports.scanScene(client);
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        ports.add(event.getGameObject());
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event) {
        ports.remove(event.getGameObject());
    }

    @Subscribe
    public void onWorldViewUnloaded(WorldViewUnloaded event) {
        ports.unload(event.getWorldView());
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"harbourmaster".equals(event.getGroup())) {
            return;
        }
        clientThread.invokeLater(() -> {
            previousInputs = null;
            if (running) {
                refresh();
            }
        });
    }

    private void clear() {
        ports.clear();
        noticeboard.clear();
        routeTracker.clear();
        previousInputs = null;
        snapshot = HarbourmasterSnapshot.empty();
    }

    private void refresh() {
        if (client.getGameState() != GameState.LOGGED_IN) {
            return;
        }
        if (!catalog.isLoaded()) {
            catalog.load(client);
        }
        noticeboard.scan(client, catalog);
        if (noticeboard.isDetailsOpen() || noticeboard.isOpeningDetails()) {
            return;
        }
        ports.update(client, noticeboard.isOpen() ? noticeboard.getPort() : null);
        List<ActiveTask> held = activeTasks.read(
                client::getVarbitValue, client::getVarpValue, catalog::byId, catalog::isIgnoredTask, ports.getStart());
        Map<Integer, CargoTracker.Destination> destinations = cargo.destinations(held, ports.getDock());
        boolean depositCargo = cargo.needsDeposit(client, destinations, ports.getDock());
        int level = client.getRealSkillLevel(Skill.SAILING);
        int capacity = Math.min(5, 1 + client.getVarbitValue(VarbitID.PORT_TASK_EXTRA_SLOTS_UNLOCKED));
        int freeSlots = Math.max(0, capacity - activeTasks.occupiedSlots(client::getVarbitValue));
        List<Object> inputs = Arrays.asList(
                held,
                noticeboard.getOffers(),
                noticeboard.getPort(),
                noticeboard.isOpen(),
                ports.getStart(),
                ports.getBoatPosition(),
                ports.getDock(),
                level,
                freeSlots,
                depositCargo,
                config.enableOptimizer());
        if (inputs.equals(previousInputs)) {
            return;
        }
        previousInputs = inputs;
        RoutePlan route;
        if (config.enableOptimizer()) {
            route = routeTracker.update(ports.getStart(), ports.getBoatPosition(), held);
        } else {
            routeTracker.clear();
            route = RoutePlan.unavailable("Route optimiser disabled");
        }
        boolean rankOffers = noticeboard.isOpen() && config.rankOffers();
        RoutePlan base = rankOffers && config.enableOptimizer()
                ? optimizer.optimizeForExperience(noticeboard.getPort(), held)
                : route;
        List<OfferScore> offers = rankOffers
                ? ranker.rank(noticeboard.getPort(), held, noticeboard.getOffers(), level, freeSlots, base)
                : List.of();
        snapshot = new HarbourmasterSnapshot(
                true,
                route,
                offers,
                noticeboard.isOpen(),
                freeSlots,
                DockChecklist.at(ports.getDock(), held),
                destinations,
                depositCargo);
    }

    public HarbourmasterSnapshot getSnapshot() {
        return snapshot;
    }

    public NoticeboardTracker getNoticeboard() {
        return noticeboard;
    }

    public PortTracker getPorts() {
        return ports;
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.NavigationPath;
import com.harbourmaster.tracker.PortTracker;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public final class NavigationOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;

    @Inject
    public NavigationOverlay(Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showWorldRoute()) {
            return null;
        }
        Graphics2D drawing = (Graphics2D) graphics.create();
        drawing.clipRect(
                client.getViewportXOffset(),
                client.getViewportYOffset(),
                client.getViewportWidth(),
                client.getViewportHeight());
        drawPaths(drawing, client, plugin.getSnapshot(), config, false);
        drawing.dispose();
        return null;
    }

    static void drawPaths(
            Graphics2D graphics,
            Client client,
            HarbourmasterSnapshot state,
            HarbourmasterConfig config,
            boolean minimap) {
        WorldPoint position = PortTracker.position(client);
        if (position == null) {
            return;
        }
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        for (int leg = state.navigation.size() - 1; leg >= 0; leg--) {
            NavigationPath path = state.navigation.get(leg);
            boolean current = path.leg == state.currentLeg;
            if (!current && !config.showCompleteRoute()) {
                continue;
            }
            graphics.setColor(current ? config.activeRouteColor() : config.futureRouteColor());
            graphics.setStroke(new BasicStroke(current ? 2.5f : 1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Point previous = null;
            int segment = 0;
            for (NavigationPath.Sample point : path.points) {
                if (point.tile.distanceTo(position) > (minimap ? 32 : 100)) {
                    previous = null;
                    continue;
                }
                LocalPoint local = localPoint(client, point);
                Point canvas = local == null
                        ? null
                        : minimap
                                ? Perspective.localToMinimap(client, local)
                                : Perspective.localToCanvas(
                                        client,
                                        local,
                                        client.getTopLevelWorldView().getPlane());
                if (canvas != null && previous != null) {
                    drawSegment(graphics, previous, canvas, ++segment % 6 == 0);
                }
                previous = canvas;
            }
        }
    }

    static LocalPoint localPoint(Client client, NavigationPath.Sample sample) {
        LocalPoint tile = localPoint(client, sample.tile);
        if (tile == null) {
            return null;
        }
        double horizontal = sample.offsetX * Perspective.LOCAL_TILE_SIZE;
        double vertical = sample.offsetY * Perspective.LOCAL_TILE_SIZE;
        if (client.getTopLevelWorldView().isInstance()) {
            int template = client.getTopLevelWorldView()
                    .getInstanceTemplateChunks()[client.getTopLevelWorldView().getPlane()][tile.getSceneX() / 8][
                    tile.getSceneY() / 8];
            int rotation = (template >> 1) & 3;
            for (int turn = 0; turn < rotation; turn++) {
                double previousHorizontal = horizontal;
                horizontal = vertical;
                vertical = -previousHorizontal;
            }
        }
        return new LocalPoint(
                tile.getX() + (int) Math.round(horizontal),
                tile.getY() + (int) Math.round(vertical),
                tile.getWorldView());
    }

    static LocalPoint localPoint(Client client, WorldPoint point) {
        for (WorldPoint instance : WorldPoint.toLocalInstance(client.getTopLevelWorldView(), point)) {
            LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), instance);
            if (local != null) {
                return local;
            }
        }
        return null;
    }

    static void drawSegment(Graphics2D graphics, Point from, Point to, boolean arrow) {
        graphics.drawLine(from.getX(), from.getY(), to.getX(), to.getY());
        if (!arrow) {
            return;
        }
        double angle = Math.atan2(to.getY() - from.getY(), to.getX() - from.getX());
        int middleX = (from.getX() + to.getX()) / 2;
        int middleY = (from.getY() + to.getY()) / 2;
        for (double side : new double[] {angle - 0.55, angle + 0.55}) {
            graphics.drawLine(
                    middleX, middleY, middleX - (int) (7 * Math.cos(side)), middleY - (int) (7 * Math.sin(side)));
        }
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
