import com.harbourmaster.model.OfferScore;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

public final class NoticeboardOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;
    private final TooltipManager tooltips;

    @Inject
    public NoticeboardOverlay(
            Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config, TooltipManager tooltips) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.tooltips = tooltips;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        HarbourmasterSnapshot state = plugin.getSnapshot();
        boolean openingDetails = plugin.getNoticeboard().isOpeningDetails();
        if (!config.rankOffers()
                || !state.boardOpen
                || visible(InterfaceID.Worldmap.CONTENT)
                || visible(InterfaceID.PortTaskInfo.WINDOW)
                || !openingDetails && !visible(InterfaceID.PortTaskBoard.CONTAINER)) {
            return null;
        }
        Graphics2D drawing = (Graphics2D) graphics.create();
        drawing.setColor(config.bestOfferColor());
        drawing.setStroke(new BasicStroke(3));
        Point mouse = client.getMouseCanvasPosition();
        for (OfferScore offer : state.offers) {
            Widget widget = plugin.getNoticeboard().getWidgets().get(offer.task.databaseRow);
            if (widget == null || !openingDetails && widget.isHidden()) {
                continue;
            }
            Rectangle bounds = widget.getBounds();
            if (offer.bundle != null) {
                drawing.draw(bounds);
            }
            if (!openingDetails && bounds.contains(mouse.getX(), mouse.getY())) {
                tooltips.add(new Tooltip(details(offer)));
            }
        }
        if (!openingDetails
                && state.offers.stream().anyMatch(OfferScore::scorable)
                && state.offers.stream().noneMatch(offer -> offer.bundle != null)) {
            String message = "No worthwhile offer right now";
            Rectangle bounds = client.getWidget(InterfaceID.PortTaskBoard.FRAME).getBounds();
            drawing.setFont(FontManager.getRunescapeSmallFont());
            OverlayUtil.renderTextLocation(
                    drawing,
                    new Point(
                            bounds.x + (bounds.width - drawing.getFontMetrics().stringWidth(message)) / 2,
                            bounds.y + bounds.height - 11),
                    message,
                    Color.WHITE);
        }
        drawing.dispose();
        return null;
    }

    private boolean visible(int component) {
        Widget widget = client.getWidget(component);
        return widget != null && !widget.isHidden();
    }

    private String details(OfferScore offer) {
        StringBuilder text = new StringBuilder(offer.task.name);
        text.append("<br>").append(offer.task.pickup.name).append(" to ").append(offer.task.delivery.name);
        text.append(
                offer.task.experience < 0
                        ? "<br>XP unavailable"
                        : String.format(Locale.ENGLISH, "<br>%,d xp (base)", offer.task.experience));
        if (!offer.eligible()) {
            text.append("<br>").append(offer.unavailableReason);
        } else if (!offer.routeAvailable) {
            text.append("<br>Route unavailable");
        } else {
            text.append(String.format(Locale.ENGLISH, "<br>+%,.0f sailing tiles", offer.marginalDistance));
            if (offer.task.experience >= 0) {
                text.append("<br>").append(efficiency(offer.score, offer.freeTravel));
            }
        }
        if (offer.task.delivery.noticeboardObject < 0) {
            text.append("<br>No task board at this delivery port");
        }
        if (offer.bundle != null && offer.bundle.tasks.size() > 1) {
            OfferBundle bundle = offer.bundle;
            text.append("<br><br>Recommended combination");
            for (CourierTask task : bundle.tasks) {
                text.append("<br>- ").append(task.name);
            }
            text.append(String.format(
                    Locale.ENGLISH,
                    "<br>%,d xp combined (base)<br>+%,.0f sailing tiles combined<br>%s",
                    bundle.experience,
                    bundle.marginalDistance,
                    efficiency(bundle.score, bundle.freeTravel)));
        }
        return text.toString();
    }

    private String efficiency(double score, boolean freeTravel) {
        return freeTravel ? "No added sailing" : String.format(Locale.ENGLISH, "%.1f xp per added tile", score);
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.data.CargoHoldObjects;
import com.harbourmaster.model.Port;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

public final class PortTracker {
    private static final int DOCK_APPROACH_DISTANCE = 3;
    private final Set<GameObject> objects = new HashSet<>();
    private Port dock;
    private Port associated;
    private Port start;
    private WorldPoint boatPosition;

    public void add(GameObject object) {
        if (Port.fromObject(object.getId()) != null
                || CargoHoldObjects.IDS.contains(object.getId())
                || object.getId() == ObjectID.SAILING_GANGPLANK_PROXY) {
            objects.add(object);
        }
    }

    public void remove(GameObject object) {
        objects.remove(object);
    }

    public void unload(WorldView view) {
        objects.removeIf(object -> object.getWorldView() == view);
    }

    public void scanScene(Client client) {
        objects.clear();
        WorldView top = client.getTopLevelWorldView();
        if (top == null) {
            return;
        }
        scan(top);
        for (WorldEntity entity : top.worldEntities()) {
            scan(entity.getWorldView());
        }
    }

    private void scan(WorldView view) {
        if (view == null) {
            return;
        }
        for (Tile[][] plane : view.getScene().getTiles()) {
            for (Tile[] column : plane) {
                for (Tile tile : column) {
                    if (tile == null) {
                        continue;
                    }
                    for (GameObject object : tile.getGameObjects()) {
                        if (object != null) {
                            add(object);
                        }
                    }
                }
            }
        }
    }

    public void update(Client client, Port board) {
        dock = null;
        WorldPoint location = position(client);
        if (location == null && board == null) {
            return;
        }
        boolean atSea = client.getVarbitValue(VarbitID.SAILING_TRANSMIT_IS_AT_SEA) != 0;
        boolean aboard = client.getLocalPlayer() != null
                && !client.getLocalPlayer().getWorldView().isTopLevel();
        boatPosition = aboard && board == null ? position(client, true) : null;
        int closestObject = 25;
        for (GameObject object : objects) {
            Port port = Port.fromObject(object.getId());
            if (location == null || port == null || !object.getWorldView().isTopLevel()) {
                continue;
            }
            int approachDistance =
                    boatPosition == null ? Integer.MAX_VALUE : boatPosition.distanceTo(port.navigationLocation);
            if (atSea && approachDistance > DOCK_APPROACH_DISTANCE) {
                continue;
            }
            int distance = approachDistance <= DOCK_APPROACH_DISTANCE
                    ? approachDistance
                    : location.distanceTo(WorldPoint.fromLocalInstance(client, object.getLocalLocation()));
            if (distance < closestObject) {
                closestObject = distance;
                dock = port;
            }
        }
        if (dock != null) {
            associated = dock;
        }
        if (board != null) {
            start = board;
            associated = board;
        } else if (dock != null) {
            start = dock;
        } else if (associated != null) {
            start = associated;
        } else {
            int nearest = 257;
            start = null;
            for (Port port : Port.values()) {
                int distance = location.distanceTo(port.navigationLocation);
                if (distance < nearest) {
                    nearest = distance;
                    start = port;
                }
            }
            if (atSea || aboard) {
                associated = start;
            }
        }
    }

    public static WorldPoint position(Client client) {
        return position(client, false);
    }

    private static WorldPoint position(Client client, boolean boatAnchor) {
        Player player = client.getLocalPlayer();
        WorldView top = client.getTopLevelWorldView();
        if (player == null || top == null) {
            return null;
        }
        LocalPoint location = player.getLocalLocation();
        if (!player.getWorldView().isTopLevel()) {
            WorldEntity entity =
                    top.worldEntities().byIndex(player.getWorldView().getId());
            if (entity == null) {
                return null;
            }
            location = boatAnchor ? entity.getLocalLocation() : entity.transformToMainWorld(location);
        }
        return WorldPoint.fromLocalInstance(client, location);
    }

    public void clear() {
        objects.clear();
        dock = null;
        associated = null;
        start = null;
        boatPosition = null;
    }

    public List<GameObject> getObjects() {
        return List.copyOf(objects);
    }

    public Port getDock() {
        return dock;
    }

    public WorldPoint getBoatPosition() {
        return boatPosition;
    }

    public Port getStart() {
        return start;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.model.RouteStop;
import com.harbourmaster.optimizer.RouteOptimizer;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class RouteTracker {
    private final RouteOptimizer optimizer;
    private RouteStop pendingStop;
    private RoutePlan previousPlan;
    private List<ActiveTask> previousTasks = List.of();

    public RouteTracker(RouteOptimizer optimizer) {
        this.optimizer = optimizer;
    }

    public RoutePlan update(Port start, List<ActiveTask> tasks) {
        return update(start, null, tasks);
    }

    public RoutePlan update(Port start, WorldPoint boatPosition, List<ActiveTask> tasks) {
        if (previousPlan != null && previousPlan.available && tasks.equals(previousTasks)) {
            previousPlan = optimizer.relocate(previousPlan, start, boatPosition);
            return previousPlan;
        }
        if (tasks.stream().anyMatch(task -> previousTasks.stream()
                .noneMatch(previous -> previous.slot == task.slot && previous.taskId == task.taskId))) {
            pendingStop = null;
        }
        Port firstStop = pendingStop != null && pendingStop.events.stream().anyMatch(event -> pending(event, tasks))
                ? pendingStop.port
                : null;
        RoutePlan route = optimizer.optimizeForExperience(start, boatPosition, tasks, firstStop);
        previousTasks = List.copyOf(tasks);
        if (route.available) {
            pendingStop = route.stops.isEmpty() ? null : route.stops.get(0);
        }
        previousPlan = route;
        return route;
    }

    private static boolean pending(RouteEvent event, List<ActiveTask> tasks) {
        for (ActiveTask task : tasks) {
            if (task.slot == event.slot && task.taskId == event.task.id) {
                return task.definition == null
                        || (event.action == RouteEvent.Action.PICKUP
                                        ? task.pickupRemaining()
                                        : task.deliveryRemaining())
                                > 0;
            }
        }
        return false;
    }

    public void clear() {
        pendingStop = null;
        previousPlan = null;
        previousTasks = List.of();
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

public final class ActiveTaskTracker {
    private static final int[] CREW_CARGO_ITEMS = {
        VarPlayerID.SAILING_CREW_HELD_CARGO_0,
        VarPlayerID.SAILING_CREW_HELD_CARGO_1,
        VarPlayerID.SAILING_CREW_HELD_CARGO_2,
        VarPlayerID.SAILING_CREW_HELD_CARGO_3,
        VarPlayerID.SAILING_CREW_HELD_CARGO_4
    };
    private static final int[] CREW_CARGO_AMOUNTS = {
        VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_1_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_2_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_3_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_4_AMOUNT
    };

    public List<ActiveTask> read(
            IntUnaryOperator varbit,
            IntUnaryOperator varplayer,
            IntFunction<CourierTask> catalog,
            IntPredicate ignoredTask,
            Port port) {
        List<ActiveTask> active = new ArrayList<>();
        for (int slot = 0; slot < TaskVarbits.IDS.length; slot++) {
            int id = varbit.applyAsInt(TaskVarbits.IDS[slot]);
            if (id == 0 || ignoredTask.test(id)) {
                continue;
            }
            active.add(new ActiveTask(
                    slot,
                    id,
                    catalog.apply(id),
                    varbit.applyAsInt(TaskVarbits.TAKEN[slot]),
                    varbit.applyAsInt(TaskVarbits.DELIVERED[slot])));
        }

        Map<Integer, Integer> crewCargo = new HashMap<>();
        for (int crew = 0; crew < CREW_CARGO_ITEMS.length; crew++) {
            int amount = varbit.applyAsInt(CREW_CARGO_AMOUNTS[crew]);
            if (amount > 0) {
                crewCargo.merge(varplayer.applyAsInt(CREW_CARGO_ITEMS[crew]), amount, Integer::sum);
            }
        }
        for (int index = 0; index < active.size(); index++) {
            ActiveTask task = active.get(index);
            if (task.definition == null || task.isFinished() || task.definition.pickup != port) {
                continue;
            }
            int carriedByCrew = crewCargo.getOrDefault(task.definition.itemId, 0);
            if (carriedByCrew > 0) {
                active.set(
                        index,
                        new ActiveTask(
                                task.slot,
                                task.taskId,
                                task.definition,
                                Math.min(task.definition.quantity, task.cargoTaken + carriedByCrew),
                                task.cargoDelivered));
            }
        }
        return List.copyOf(active);
    }

    public int occupiedSlots(IntUnaryOperator varbit) {
        int occupied = 0;
        for (int identifier : TaskVarbits.IDS) {
            if (varbit.applyAsInt(identifier) != 0) {
                occupied++;
            }
        }
        return occupied;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.ActiveTask;
