package com.harbourmaster.data;

import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;

@Singleton
public final class PortTaskCatalog {
    private static final Set<Integer> SPECIAL_TASK_ROWS = Set.of(
            DBTableID.PortTask.Row.PORT_TASK_SAILING_INTRO,
            DBTableID.PortTask.Row.PORT_TASK_PRYING_TIMES,
            DBTableID.PortTask.Row.PORT_TASK_BLANK,
            DBTableID.PortTask.Row.PORT_TASK_LOCKED);
    private final TaskRewards rewards = new TaskRewards();
    private Map<Integer, CourierTask> byId = Map.of();
    private Map<Integer, CourierTask> byRow = Map.of();
    private Set<Integer> ignoredTaskIds = Set.of();
    private Set<Integer> ignoredRows = Set.of();
    private boolean loaded;

    public void load(Client client) {
        Map<Integer, CourierTask> identifiers = new HashMap<>();
        Map<Integer, CourierTask> rows = new HashMap<>();
        Set<Integer> ignoredIdentifiers = new HashSet<>();
        Set<Integer> ignoredDatabaseRows = new HashSet<>(SPECIAL_TASK_ROWS);
        for (int row : client.getDBTableRows(DBTableID.PortTask.ID)) {
            if (SPECIAL_TASK_ROWS.contains(row)) {
                continue;
            }
            if (integer(client, row, DBTableID.PortTask.COL_TASK_TYPE, 0) != 0) {
                ignoredIdentifiers.add(integer(client, row, DBTableID.PortTask.COL_TASK_ID, 0));
                ignoredDatabaseRows.add(row);
                continue;
            }
            CourierTask task = readRow(client, row);
            identifiers.put(task.id, task);
            rows.put(row, task);
        }
        byId = Map.copyOf(identifiers);
        byRow = Map.copyOf(rows);
        ignoredTaskIds = Set.copyOf(ignoredIdentifiers);
        ignoredRows = Set.copyOf(ignoredDatabaseRows);
        loaded = true;
    }

    private CourierTask readRow(Client client, int row) {
        int item = integer(client, row, DBTableID.PortTask.COL_CARGO, 0);
        return new CourierTask(
                integer(client, row, DBTableID.PortTask.COL_TASK_ID, 0),
                row,
                (String) field(client, row, DBTableID.PortTask.COL_NAME, 0),
                integer(client, row, DBTableID.PortTask.COL_LEVEL_REQUIRED, 0),
                port(client, row, DBTableID.PortTask.COL_STARTING_PORT),
                item,
                client.getItemDefinition(item).getName(),
                integer(client, row, DBTableID.PortTask.COL_CARGO, 1),
                rewards.forRow(row),
                port(client, row, DBTableID.PortTask.COL_CARGO_PORT),
                port(client, row, DBTableID.PortTask.COL_ENDING_PORT));
    }

    private static Port port(Client client, int row, int column) {
        return Objects.requireNonNull(
                Port.fromDatabaseRow(integer(client, row, column, 0)), "Unknown port in task row " + row);
    }

    private static Object field(Client client, int row, int column, int tuple) {
        return client.getDBTableField(row, column, tuple)[0];
    }

    private static int integer(Client client, int row, int column, int tuple) {
        return (Integer) field(client, row, column, tuple);
    }

    public CourierTask byId(int id) {
        return byId.get(id);
    }

    public CourierTask byRow(int row) {
        return byRow.get(row);
    }

    public boolean isIgnoredTask(int id) {
        return ignoredTaskIds.contains(id);
    }

    public boolean isIgnoredRow(int row) {
        return ignoredRows.contains(row);
    }

    public boolean isLoaded() {
        return loaded;
    }
}

package com.harbourmaster.optimizer;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.model.RouteStop;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class RouteOptimizer {
    private static final double EPSILON = 0.0000001;
    private final PortGraph graph;

    public RouteOptimizer(PortGraph graph) {
        this.graph = graph;
    }

    public RoutePlan optimize(Port start, List<ActiveTask> tasks) {
        return optimize(start, null, tasks, null);
    }

    public RoutePlan optimize(Port start, WorldPoint boatPosition, List<ActiveTask> tasks, Port firstStop) {
        return plan(start, boatPosition, tasks, firstStop, false);
    }

    public RoutePlan optimizeForExperience(
            Port start, WorldPoint boatPosition, List<ActiveTask> tasks, Port firstStop) {
        return plan(start, boatPosition, tasks, firstStop, true);
    }

    public RoutePlan optimizeForExperience(Port start, List<ActiveTask> tasks) {
        return optimizeForExperience(start, null, tasks, null);
    }

    private RoutePlan plan(
            Port start, WorldPoint boatPosition, List<ActiveTask> tasks, Port firstStop, boolean prioritizeExperience) {
        List<RouteEvent> events = new ArrayList<>();
        List<Integer> prerequisites = new ArrayList<>();
        for (ActiveTask active : tasks) {
            if (active.definition == null) {
                return RoutePlan.unavailable("Unrecognized active task " + active.taskId);
            }
            if (active.isFinished()) {
                continue;
            }
            CourierTask task = active.definition;
            int pickupMask = 0;
            if (active.pickupRemaining() > 0) {
                pickupMask = 1 << events.size();
                events.add(new RouteEvent(
                        active.slot, task, RouteEvent.Action.PICKUP, task.pickup, active.pickupRemaining()));
                prerequisites.add(0);
            }
            events.add(new RouteEvent(
                    active.slot, task, RouteEvent.Action.DELIVER, task.delivery, active.deliveryRemaining()));
            prerequisites.add(pickupMask);
        }
        if (events.isEmpty()) {
            return RoutePlan.empty();
        }
        if (start == null && boatPosition == null) {
            return RoutePlan.unavailable("Visit a known port to establish the route start");
        }
        int count = events.size();
        int complete = (1 << count) - 1;
        double[] outstanding = new double[complete + 1];
        if (prioritizeExperience) {
            double slotValue = Math.max(
                    1,
                    events.stream()
                            .filter(event -> event.action == RouteEvent.Action.DELIVER && event.task.experience >= 0)
                            .mapToInt(event -> event.task.experience)
                            .average()
                            .orElse(1));
            double[] weights = new double[count];
            for (int event = 0; event < count; event++) {
                if (events.get(event).action == RouteEvent.Action.DELIVER) {
                    weights[event] = Math.max(0, events.get(event).task.experience) + slotValue;
                    outstanding[0] += weights[event];
                }
            }
            for (int mask = 1; mask <= complete; mask++) {
                outstanding[mask] = outstanding[mask & (mask - 1)] - weights[Integer.numberOfTrailingZeros(mask)];
            }
        } else {
            Arrays.fill(outstanding, 1);
        }
        RouteLeg[][] journeys = new RouteLeg[count + 1][count];
        for (int destination = 0; destination < count; destination++) {
            journeys[count][destination] = journey(start, boatPosition, events.get(destination).port);
            for (int origin = 0; origin < count; origin++) {
                journeys[origin][destination] = graph.route(events.get(origin).port, events.get(destination).port)
                        .orElse(null);
            }
        }
        double[][] costs = new double[complete + 1][count];
        double[][] distances = new double[complete + 1][count];
        int[][] parents = new int[complete + 1][count];
        int[][] sailings = new int[complete + 1][count];
        for (int mask = 0; mask <= complete; mask++) {
            Arrays.fill(costs[mask], Double.POSITIVE_INFINITY);
            Arrays.fill(parents[mask], -1);
        }
        for (int event = 0; event < count; event++) {
            RouteLeg journey = journeys[count][event];
            if (prerequisites.get(event) == 0
                    && journey != null
                    && (firstStop == null || events.get(event).port == firstStop)) {
                costs[1 << event][event] = journey.distance * outstanding[0];
                distances[1 << event][event] = journey.distance;
                sailings[1 << event][event] = journey.from == journey.to ? 0 : 1;
            }
        }
        for (int visited = 1; visited <= complete; visited++) {
            for (int previous = 0; previous < count; previous++) {
                if (!Double.isFinite(costs[visited][previous])) {
                    continue;
                }
                for (int next = 0; next < count; next++) {
                    int bit = 1 << next;
                    RouteLeg journey = journeys[previous][next];
                    if ((visited & bit) != 0
                            || (visited & prerequisites.get(next)) != prerequisites.get(next)
                            || journey == null) {
                        continue;
                    }
                    int combined = visited | bit;
                    double cost = costs[visited][previous] + journey.distance * outstanding[visited];
                    double distance = distances[visited][previous] + journey.distance;
                    int sailCount = sailings[visited][previous] + (journey.from == journey.to ? 0 : 1);
                    if (better(
                            cost,
                            distance,
                            sailCount,
                            costs[combined][next],
                            distances[combined][next],
                            sailings[combined][next])) {
                        costs[combined][next] = cost;
                        distances[combined][next] = distance;
                        sailings[combined][next] = sailCount;
                        parents[combined][next] = previous;
                    }
                }
            }
        }
        int last = -1;
        for (int event = 0; event < count; event++) {
            if (Double.isFinite(costs[complete][event])
                    && (last < 0
                            || better(
                                    costs[complete][event],
                                    distances[complete][event],
                                    sailings[complete][event],
                                    costs[complete][last],
                                    distances[complete][last],
                                    sailings[complete][last]))) {
                last = event;
            }
        }
        if (last < 0) {
            return RoutePlan.unavailable("Route unavailable: unknown or disconnected port");
        }

        double distance = distances[complete][last];
        List<RouteEvent> ordered = new ArrayList<>();
        for (int remaining = complete; last >= 0; ) {
            ordered.add(events.get(last));
            int parent = parents[remaining][last];
            remaining ^= 1 << last;
            last = parent;
        }
        Collections.reverse(ordered);
        List<RouteLeg> legs = new ArrayList<>();
        List<RouteStop> stops = new ArrayList<>();
        Port position = start;
        if (boatPosition != null) {
            legs.add(journey(start, boatPosition, ordered.get(0).port));
            position = ordered.get(0).port;
        }
        for (RouteEvent event : ordered) {
            if (position != event.port) {
                legs.add(graph.route(position, event.port).orElseThrow(IllegalStateException::new));
                position = event.port;
            }
            if (stops.isEmpty() || stops.get(stops.size() - 1).port != event.port) {
                stops.add(new RouteStop(event.port, List.of(event)));
            } else {
                List<RouteEvent> grouped = new ArrayList<>(stops.remove(stops.size() - 1).events);
                grouped.add(event);
                stops.add(new RouteStop(event.port, grouped));
            }
        }
        return new RoutePlan(true, "", distance, legs, stops);
    }

    public RoutePlan relocate(RoutePlan plan, Port start, WorldPoint boatPosition) {
        if (plan.stops.isEmpty()) {
            return RoutePlan.empty();
        }
        Port destination = plan.stops.get(0).port;
        RouteLeg approach = journey(start, boatPosition, destination);
        if (approach == null) {
            return RoutePlan.unavailable("Route unavailable: unknown or disconnected port");
        }
        List<RouteLeg> legs = new ArrayList<>(plan.legs);
        double distance = plan.distance;
        if (!legs.isEmpty() && legs.get(0).to == destination) {
            distance -= legs.remove(0).distance;
        }
        if (boatPosition != null || start != destination) {
            legs.add(0, approach);
            distance += approach.distance;
        }
        return new RoutePlan(true, "", distance, legs, plan.stops);
    }

    private RouteLeg journey(Port start, WorldPoint boatPosition, Port destination) {
        return (boatPosition == null
                        ? graph.route(start, destination)
                        : graph.routeFromPosition(boatPosition, destination))
                .orElse(null);
    }

    private static boolean better(
            double cost,
            double distance,
            int sailings,
            double existing,
            double existingDistance,
            int existingSailings) {
        return cost < existing - EPSILON
                || (Math.abs(cost - existing) < EPSILON
                        && (distance < existingDistance - EPSILON
                                || (Math.abs(distance - existingDistance) < EPSILON && sailings < existingSailings)));
    }
}

package com.harbourmaster.optimizer;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.OfferBundle;
import com.harbourmaster.model.OfferScore;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RoutePlan;
import java.util.ArrayList;
import java.util.List;

public final class OfferRanker {
    private final RouteOptimizer optimizer;

    public OfferRanker(RouteOptimizer optimizer) {
        this.optimizer = optimizer;
    }

    public List<OfferScore> rank(
            Port start,
            List<ActiveTask> held,
            List<CourierTask> offers,
            int sailingLevel,
            int freeSlots,
            RoutePlan base) {
        List<OfferScore> scores = new ArrayList<>();
        for (CourierTask task : offers) {
            String reason = eligibility(task, held, sailingLevel, freeSlots);
            if (!reason.isEmpty() || !base.available) {
                scores.add(new OfferScore(task, reason, false, 0, 0, false));
                continue;
            }
            List<ActiveTask> candidate = new ArrayList<>(held);
            candidate.add(new ActiveTask(5, task.id, task, 0, 0));
            double marginal = Math.max(0, optimizer.optimizeForExperience(start, candidate).distance - base.distance);
            boolean free = marginal < 0.0000001;
            scores.add(new OfferScore(
                    task,
                    reason,
                    true,
                    free ? 0 : marginal,
                    !free && task.experience >= 0 ? task.experience / marginal : 0,
                    free));
        }
        OfferBundle bundle = bestBundle(start, held, scores, freeSlots, base);
        if (bundle != null) {
            scores.replaceAll(score -> bundle.tasks.contains(score.task) ? score.withBundle(bundle) : score);
        }
        return List.copyOf(scores);
    }

    private OfferBundle bestBundle(
            Port start, List<ActiveTask> held, List<OfferScore> scores, int freeSlots, RoutePlan base) {
        if (!base.available || freeSlots == 0) {
            return null;
        }
        List<OfferScore> eligible = new ArrayList<>();
        for (OfferScore score : scores) {
            if (score.scorable()) {
                eligible.add(score);
            }
        }
        boolean alreadyEndsWithoutBoard =
                !base.stops.isEmpty() && base.stops.get(base.stops.size() - 1).port.noticeboardObject < 0;
        OfferBundle best = null;
        for (int mask = 1; mask < (1 << eligible.size()); mask++) {
            if (Integer.bitCount(mask) > freeSlots) {
                continue;
            }
            List<CourierTask> tasks = new ArrayList<>();
            List<ActiveTask> candidate = new ArrayList<>(held);
            for (int index = 0; index < eligible.size(); index++) {
                if ((mask & (1 << index)) != 0) {
                    OfferScore score = eligible.get(index);
                    tasks.add(score.task);
                    candidate.add(new ActiveTask(5 + index, score.task.id, score.task, 0, 0));
                }
            }
            RoutePlan route = optimizer.optimizeForExperience(start, candidate);
            if (!route.available
                    || (!alreadyEndsWithoutBoard
                            && route.stops.get(route.stops.size() - 1).port.noticeboardObject < 0)) {
                continue;
            }
            OfferBundle bundle = new OfferBundle(tasks, Math.max(0, route.distance - base.distance));
            if (best == null
                    || (bundle.freeTravel && !best.freeTravel)
                    || (bundle.freeTravel == best.freeTravel
                            && (bundle.score > best.score
                                    || (bundle.score == best.score && bundle.experience > best.experience)))) {
                best = bundle;
            }
        }
        int heldExperience = held.stream()
                .filter(task -> !task.isFinished())
                .mapToInt(task -> Math.max(0, task.definition.experience))
                .sum();
        if (best != null && !best.freeTravel && heldExperience > 0 && best.score < heldExperience / base.distance) {
            return null;
        }
        return best;
    }

    public static String eligibility(CourierTask offer, List<ActiveTask> held, int level, int freeSlots) {
        for (ActiveTask active : held) {
            if (active.taskId == offer.id) {
                return "Already accepted";
            }
        }
        if (level < offer.level) {
            return "Requires Sailing " + offer.level;
        }
        if (freeSlots == 0) {
            return "No free task slots";
        }
        return "";
    }
}

